--ds-error-state-bg.shippedValue:
linear-gradient(
    145deg,
    color-mix(in srgb, var(--ds-color-error) 7%, var(--ds-surface-card-bg)),
    var(--ds-surface-panel-bg)
  )

--ds-surface-card-grid-line-strong.shippedValue:
color-mix(
    in srgb,
    var(
        --rt-premium-card-accent,
        var(--ds-signal-card-accent, var(--ds-color-primary))
      )
      8%,
    transparent
  )

